const legacyArtworks = [
{ id: 'moon-sea', name: '月色海岸', url: 'data:image/webp;base64,' },
{ id: 'magnolia', name: '玉兰来信', url: 'data:image/webp;base64,' }
];

export const zoneArtworks = [{"id": "zone-luna", "name": "月眠", "url": "data:image/webp;base64,"}, {"id": "zone-wings", "name": "羽光", "url": "data:image/webp;base64,"}, {"id": "zone-window", "name": "彩窗", "url": "data:image/webp;base64,"}, {"id": "zone-butterfly", "name": "蝶梦", "url": "data:image/webp;base64,"}, {"id": "zone-stars", "name": "星河", "url": "data:image/webp;base64,"}];
export const walletArtworks = [{"id": "card-pencil", "name": "灵感手札", "url": "data:image/webp;base64,"}, {"id": "card-windmill", "name": "风车假日", "url": "data:image/webp;base64,"}, {"id": "card-ribbon", "name": "缤纷协奏", "url": "data:image/webp;base64,"}, {"id": "card-orbit", "name": "星光旅行", "url": "data:image/webp;base64,"}, {"id": "card-garden", "name": "花园来信", "url": "data:image/webp;base64,"}];
export function artworkUrl(value: string): string { return [...zoneArtworks, ...walletArtworks, ...legacyArtworks].find(item => item.id === value)?.url || (/^(https?:\/\/|data:image\/|\/)/i.test(value) ? value : ''); }
export function normalizeArtwork(app: string, value: string): string { if (app === 'wallet' && ['moon-sea', 'magnolia'].includes(value)) return 'card-pencil'; return value; }
